// The watch pages' scripts and styles (watch/page/*.js, watch/page/*.css),
// compiled in beside the pages (watch_assets.cpp is generated by
// cmake/embed_watch_assets.cmake). A page names them by relative URLs, so each
// is served beside the page that loads it: the daemon at /NAME, the hub at
// /NAME and /runs/RUN/NAME.

#pragma once

#include <optional>
#include <string_view>

namespace gamepilot {

struct WatchAsset {
  std::string_view type;   // the Content-Type: text/javascript or text/css
  std::string_view bytes;  // the file as it is
};

// The file called `name` (watch_frame.js, watch.css, ...), or none.
std::optional<WatchAsset> watch_asset(std::string_view name);

}  // namespace gamepilot
